import java.util.*;

public class Main {
    static int n, t;
    static class Pkt {
        int x, y;
        Pkt(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
    static class Edge {
        int node, capacity;
        Edge(int node, int capacity) {
            this.node = node;
            this.capacity = capacity;
        }
    }
    static int[] delta_x = {-1, 0, 1, 0, 0};
    static int[] delta_y = {0, 1, 0, -1, 0};

    static boolean is_valid(int x, int y) {
        return (x >= 0 && x < n && y >= 0 && y < n);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        t = sc.nextInt();
        sc.nextLine();
        String[] first_map = new String[n];
        String[] second_map = new String[n];
        for (int i = 0; i < n; i++) {
            first_map[i] = sc.nextLine();
        }
        for (int i = 0; i < n; i++) {
            second_map[i] = sc.nextLine();
        }

        int[][] dist = new int[n][n];
        for (int[] row : dist)
            Arrays.fill(row, 1000);
        Pkt start_point = null;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (first_map[i].charAt(j) == 'Z') {
                    start_point = new Pkt(i, j);
                }
            }
        }
        Queue<Pkt> q = new LinkedList<>();
        dist[start_point.x][start_point.y] = 0;
        q.offer(start_point);
        while (!q.isEmpty()) {
            Pkt current = q.poll();
            for (int dir = 0; dir < 4; dir++) {
                int nx = current.x + delta_x[dir];
                int ny = current.y + delta_y[dir];
                if (is_valid(nx, ny) && first_map[nx].charAt(ny) >= '0' && first_map[nx].charAt(ny) <= '9' && dist[nx][ny] == 1000) {
                    dist[nx][ny] = dist[current.x][current.y] + 1;
                    q.offer(new Pkt(nx, ny));
                }
            }
        }

        boolean[][][][][] reachable = new boolean[60][10][10][10][10];
        for (int i = 0; i < 60; i++)
            for (int j = 0; j < 10; j++)
                for (int k = 0; k < 10; k++)
                    for (int l = 0; l < 10; l++)
                        for (int m = 0; m < 10; m++)
                            reachable[i][j][k][l][m] = false;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < 4; k++) {
                    int l = i + delta_x[k], m = j + delta_y[k];
                    if (is_valid(l, m) && first_map[i].charAt(j) >= '0' && first_map[i].charAt(j) <= '9' && first_map[l].charAt(m) >= '0' && first_map[l].charAt(m) <= '9') {
                        reachable[0][i][j][l][m] = true;
                    }
                }
            }
        }

        for (int step = 0; step <= t - 2; step++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        for (int l = 0; l < n; l++) {
                            if (!reachable[step][i][j][k][l]) continue;
                            for (int o = 0; o < 4; o++) {
                                int p = k + delta_x[o], r = l + delta_y[o];
                                if (is_valid(p, r) && first_map[p].charAt(r) >= '0' && first_map[p].charAt(r) <= '9' && dist[k][l] >= step + 2 && dist[p][r] >= step + 2) {
                                    reachable[step + 1][i][j][p][r] = true;
                                }
                            }
                        }
                    }
                }
            }
        }

        List<Pkt> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (first_map[i].charAt(j) >= '0' && first_map[i].charAt(j) <= '9') {
                    points.add(new Pkt(i, j));
                }
            }
        }

        int total_nodes = 2 * points.size() + 2;
        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < total_nodes; i++) {
            graph.add(new ArrayList<>());
        }

        for (int i = 0; i < points.size(); i++) {
            int capacity_in = first_map[points.get(i).x].charAt(points.get(i).y) - '0';
            int capacity_out = second_map[points.get(i).x].charAt(points.get(i).y) - '0';

            // source to in-node
            graph.get(0).add(new Edge(i + 1, capacity_in));
            // in-node to source
            graph.get(i + 1).add(new Edge(0, 0));
            // out-node to sink
            graph.get(points.size() + 1 + i).add(new Edge(total_nodes - 1, capacity_out));
            // sink to out-node
            graph.get(total_nodes - 1).add(new Edge(points.size() + 1 + i, 0));
        }

        for (int i = 0; i < points.size(); i++) {
            for (int j = 0; j < points.size(); j++) {
                boolean can_reach = false;
                for (int k = 0; k <= t - 1; k++) {
                    if (reachable[k][points.get(i).x][points.get(i).y][points.get(j).x][points.get(j).y]) {
                        can_reach = true;
                        break;
                    }
                }
                if (can_reach) {
                    graph.get(i + 1).add(new Edge(points.size() + 1 + j, 1000));
                    graph.get(points.size() + 1 + j).add(new Edge(i + 1, 0));
                }
            }
        }

        int max_flow = 0;
        while (true) {
            boolean[] visited = new boolean[total_nodes];
            int[] parent = new int[total_nodes];
            Arrays.fill(parent, -1);
            Queue<Integer> q2 = new LinkedList<>();
            visited[0] = true;
            q2.offer(0);
            while (!q2.isEmpty()) {
                int current_node = q2.poll();
                for (Edge e : graph.get(current_node)) {
                    if (!visited[e.node] && e.capacity > 0) {
                        visited[e.node] = true;
                        parent[e.node] = current_node;
                        q2.offer(e.node);
                    }
                }
            }
            if (parent[total_nodes - 1] == -1) break;
            int flow = Integer.MAX_VALUE;
            for (int v = total_nodes - 1; v != 0; v = parent[v]) {
                int u = parent[v];
                for (Edge e : graph.get(u)) {
                    if (e.node == v) {
                        flow = Math.min(flow, e.capacity);
                        break;
                    }
                }
            }
            max_flow += flow;
            for (int v = total_nodes - 1; v != 0; v = parent[v]) {
                int u = parent[v];
                for (Edge e : graph.get(u)) {
                    if (e.node == v) {
                        e.capacity -= flow;
                        break;
                    }
                }
                for (Edge e : graph.get(v)) {
                    if (e.node == u) {
                        e.capacity += flow;
                        break;
                    }
                }
            }
        }
        System.out.println(max_flow);
        sc.close();
    }
}
